  1: import { totalCents, type Channel, type Order } from "./order.js";
  2: 
  3: export const ORDER_PLACED_TOPIC = "orders.placed";
  4: export const ORDER_CANCELLED_TOPIC = "orders.cancelled";
  5: 
  6: /** Published when an order has been accepted and its payment authorized. */
  7: export interface OrderPlaced {
  8:   readonly type: "OrderPlaced";
  9:   readonly schemaVersion: 3;
 10:   readonly orderId: string;
 11:   readonly customerId: string;
 12:   /** Legacy field; a known ARCH-6 exception tracked in the PII baseline. */
 13:   readonly customerEmail: string;
 14:   /** ISO-8601 instant. */
 15:   readonly createdAt: string;
 16:   readonly channel: Channel;
 17:   /** ISO-4217 code. */
 18:   readonly currency: string;
 19:   /** Integer, minor units. */
 20:   readonly amountCents: number;
 21:   readonly lines: ReadonlyArray<{
 22:     readonly sku: string;
 23:     readonly qty: number;
 24:     readonly unitPriceCents: number;
 25:   }>;
 26: }
 27: 
 28: /** Published when a placed order is cancelled. */
 29: export interface OrderCancelled {
 30:   readonly type: "OrderCancelled";
 31:   readonly schemaVersion: 1;
 32:   readonly orderId: string;
 33:   readonly customerId: string;
 34:   /** ISO-8601 instant. */
 35:   readonly cancelledAt: string;
 36:   readonly reason?: string;
 37: }
 38: 
 39: export type DomainEvent = OrderPlaced | OrderCancelled;
 40: 
 41: /** The single place where an `OrderPlaced` event is built. */
 42: export function orderPlaced(order: Order): OrderPlaced {
 43:   return {
 44:     type: "OrderPlaced",
 45:     schemaVersion: 3,
 46:     orderId: order.id,
 47:     customerId: order.customerId,
 48:     customerEmail: order.customerEmail,
 49:     createdAt: order.placedAt,
 50:     channel: order.channel,
 51:     currency: order.currency,
 52:     amountCents: totalCents(order),
 53:     lines: order.lines.map((line) => ({
 54:       sku: line.sku,
 55:       qty: line.qty,
 56:       unitPriceCents: line.unitPriceCents,
 57:     })),
 58:   };
 59: }
 60: 
 61: /** The single place where an `OrderCancelled` event is built. */
 62: export function orderCancelled(order: Order, cancelledAt: string, reason?: string): OrderCancelled {
 63:   return {
 64:     type: "OrderCancelled",
 65:     schemaVersion: 1,
 66:     orderId: order.id,
 67:     customerId: order.customerId,
 68:     cancelledAt,
 69:     ...(reason === undefined ? {} : { reason }),
 70:   };
 71: }
 72: 
 73: export function topicFor(event: DomainEvent): string {
 74:   switch (event.type) {
 75:     case "OrderPlaced":
 76:       return ORDER_PLACED_TOPIC;
 77:     case "OrderCancelled":
 78:       return ORDER_CANCELLED_TOPIC;
 79:   }
 80: }
 81: 
 82: /** Partition key: all events of one order are ordered relative to each other. */
 83: export function partitionKeyFor(event: DomainEvent): string {
 84:   return event.orderId;
 85: }

